import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    failed_files = []

    if not os.path.isdir(src_folder):
        return {
            'success': False,
            'message': 'Source folder does not exist or is not a directory.',
            'failed_files': []
        }

    try:
        os.makedirs(dst_folder, exist_ok=True)
    except Exception:
        return {
            'success': False,
            'message': 'Failed to create or access destination folder.',
            'failed_files': []
        }

    files = [f for f in glob(os.path.join(src_folder, '*')) if os.path.isfile(f)]

    for file_path in files:
        filename = os.path.basename(file_path)
        gz_path = file_path + '.gz'

        try:
            process = subprocess.Popen(f'gzip -f "{file_path}"', shell=True)
            process.wait()

            if process.returncode != 0 or not os.path.exists(gz_path):
                failed_files.append(filename)
                continue

            shutil.move(gz_path, os.path.join(dst_folder, os.path.basename(gz_path)))
        except Exception:
            failed_files.append(filename)

    success = len(failed_files) == 0

    if success:
        message = 'All files were compressed and moved successfully.'
    else:
        message = 'Some files failed to compress or move.'

    return {
        'success': success,
        'message': message,
        'failed_files': failed_files
    }

import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError("Script path does not exist")

    process = subprocess.Popen(["bash", script_path])
    cpu_usage = 0.0
    memory_usage = 0
    last_memory = 0
    start_time = time.time()

    try:
        ps_process = psutil.Process(process.pid)
        ps_process.cpu_percent(interval=None)

        while True:
            if process.poll() is not None:
                break

            if time.time() - start_time >= timeout:
                if process.poll() is None:
                    process.terminate()
                    try:
                        process.wait(timeout=1)
                    except subprocess.TimeoutExpired:
                        process.kill()
                break

            try:
                if ps_process.status() == psutil.STATUS_ZOMBIE:
                    break

                cpu_usage += ps_process.cpu_percent(interval=0.1)
                current_memory = ps_process.memory_info().rss

                if current_memory > last_memory:
                    memory_usage += current_memory - last_memory

                last_memory = current_memory

            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                break

    except psutil.NoSuchProcess:
        pass

    return {
        "CPU Usage": cpu_usage,
        "Memory Usage": memory_usage
    }

import subprocess
import logging
def task_func(filepath):
    with open(filepath, "r"):
        pass

    output_file = filepath.rsplit(".", 1)[0] if "." in filepath else filepath + ".out"
    command = ["g++", filepath, "-o", output_file]

    try:
        result = subprocess.run(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, check=True)
        logging.info("Compilation successful")
        if result.stdout:
            logging.info(result.stdout)
        if result.stderr:
            logging.info(result.stderr)
    except subprocess.CalledProcessError as e:
        logging.error("Compilation failed")
        if e.stdout:
            logging.error(e.stdout)
        if e.stderr:
            logging.error(e.stderr)
        raise
